    /// <summary>
    /// The one meeting point every Campground plugin can see.
    /// <para>
    /// Jellyfin loads each plugin into its own AssemblyLoadContext, and every plugin compiles its own copy of
    /// this code, so no type defined here is the same type in two plugins. The registry therefore lives in an
    /// <see cref="AppDomain"/> data slot (visible from every load context) and holds <b>only .NET's own types</b>:
    /// <see cref="string"/>, <see cref="JsonElement"/>, <see cref="ConcurrentDictionary{TKey,TValue}"/> of
    /// <see cref="object"/>, and <see cref="Func{T,TResult}"/>/<see cref="Action{T}"/> over those.
    /// Never store a Campground type in it.
